import{_ as r,o as d,c as a,a2 as o}from"./chunks/framework.CRFziyHp.js";const c=JSON.parse('{"title":"信息展示组件","description":"","frontmatter":{},"headers":[],"relativePath":"features/ui-editor/components-display.md","filePath":"features/ui-editor/components-display.md","lastUpdated":1785013113000}'),e={name:"features/ui-editor/components-display.md"};function n(i,t,h,s,l,b){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="信息展示组件" tabindex="-1">信息展示组件 <a class="header-anchor" href="#信息展示组件" aria-label="Permalink to &quot;信息展示组件&quot;">​</a></h1><p>左侧组件库 <strong>「信息展示」</strong> 分类下的 3 个组件，用于静态信息条、公告提示和列表底部状态。在 <strong>UI管理 → 页面配置</strong> 中打开页面设计，从左侧点击即可添加到画布。</p><div class="tip custom-block"><p class="custom-block-title">通用说明</p><ul><li>属性在右侧 <strong>属性</strong> Tab 配置；外边距、背景、圆角等在 <strong>样式</strong> Tab 配置（详见 <a href="/features/ui-editor/styles-and-actions">样式与点击动作</a>）。</li><li>单位 <strong>rpx</strong> 为响应式像素，750rpx 约等于屏幕全宽。</li></ul></div><hr><h2 id="列表-xiaoyi-list" tabindex="-1">列表（xiaoyi-list） <a class="header-anchor" href="#列表-xiaoyi-list" aria-label="Permalink to &quot;列表（xiaoyi-list）&quot;">​</a></h2><h3 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>通用 <strong>设置式列表</strong>：每一行可带左侧图标或图片、标题、副标题、右侧文字，并配置点击跳转。适合「功能入口」「关于我们」「联系客服」等 <strong>内容由您手动填写</strong> 的场景，不会自动拉取笔记或圈子数据。</p><h3 id="适用页面" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面类型</th><th>是否常用</th></tr></thead><tbody><tr><td>应用首页、发现页</td><td>较少，多用于快捷入口</td></tr><tr><td>自定义页面</td><td>常用</td></tr><tr><td>个人中心、设置等面板页</td><td>常用（菜单行列表）</td></tr><tr><td>服务表单页</td><td>一般不用</td></tr></tbody></table><h3 id="属性配置" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><p><strong>列表项（可添加多条）</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>标题</td><td>主文案，必填</td></tr><tr><td>副标题</td><td>可选，显示在标题下方</td></tr><tr><td>右侧文字</td><td>可选，如「已开通」「99+」</td></tr><tr><td>左侧图标</td><td>三选一：<strong>字体图标</strong> / <strong>图片</strong> / <strong>无</strong></td></tr><tr><td>图标名 / 图片 URL</td><td>左侧为图标或图片时填写；图标可点「选择」从图标库挑选</td></tr><tr><td>图标颜色</td><td>仅字体图标；可覆盖全局默认色</td></tr><tr><td>点击动作</td><td>点击该行时跳转的页面或动作</td></tr></tbody></table><p><strong>全局样式类属性</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>图标大小 / 圆角</td><td>左侧图标或图片的尺寸与圆角（rpx）</td></tr><tr><td>标题字号 / 颜色 / 字重</td><td>主标题样式</td></tr><tr><td>副标题字号 / 颜色</td><td>副标题样式</td></tr><tr><td>右侧文字字号 / 颜色</td><td>右侧辅助文字</td></tr><tr><td>分割线</td><td>是否显示行与行之间的分割线</td></tr><tr><td>分割线颜色</td><td>开启分割线时可改颜色</td></tr><tr><td>箭头</td><td>是否显示右侧「›」箭头</td></tr><tr><td>箭头颜色 / 大小</td><td>开启箭头时可改样式</td></tr><tr><td>行内边距</td><td>如 <code>28rpx 30rpx</code>，控制单行上下左右留白</td></tr></tbody></table><h3 id="样式说明" tabindex="-1">样式说明 <a class="header-anchor" href="#样式说明" aria-label="Permalink to &quot;样式说明&quot;">​</a></h3><p>在 <strong>样式</strong> Tab 配置整块列表的外边距、背景色、圆角等。单行内部的间距主要由 <strong>行内边距</strong> 控制；若需卡片式列表，可给组件加背景色和圆角。</p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>每一行需单独配置 <strong>点击动作</strong>，否则点击无反应。</li><li>左侧 <strong>图片</strong> 与 <strong>字体图标</strong> 在同一行里二选一，不要同时填两项 expecting 叠加。</li><li>列表内容不会随用户或业务数据自动更新，改文案后需 <strong>保存并启用</strong> 页面配置。</li></ul><hr><h2 id="通知栏-xiaoyi-notice" tabindex="-1">通知栏（xiaoyi-notice） <a class="header-anchor" href="#通知栏-xiaoyi-notice" aria-label="Permalink to &quot;通知栏（xiaoyi-notice）&quot;">​</a></h2><h3 id="说明-1" tabindex="-1">说明 <a class="header-anchor" href="#说明-1" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>页面顶部的 <strong>公告 / 通知横条</strong>，左侧可显示图标或图片，中间为通知文字，可选右侧操作按钮或关闭按钮。适合活动通知、版本提示、平台规则说明等。</p><h3 id="适用页面-1" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-1" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面类型</th><th>是否常用</th></tr></thead><tbody><tr><td>应用首页、发现页</td><td>常用</td></tr><tr><td>自定义页面</td><td>常用</td></tr><tr><td>面板类页面</td><td>按需</td></tr><tr><td>服务表单页</td><td>较少</td></tr></tbody></table><h3 id="属性配置-1" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置-1" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><p><strong>内容</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>通知文字</td><td>横条上显示的主文案</td></tr></tbody></table><p><strong>左侧图标（优先级：图片 ＞ 字体图标 ＞ 文字/emoji）</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>图片 URL</td><td>填则优先显示图片；可从媒体库选择</td></tr><tr><td>图片边长 / 圆角</td><td>左侧图片尺寸与圆角（rpx）</td></tr><tr><td>图标字体名</td><td>无图片时使用；可点「选择」</td></tr><tr><td>图标前缀</td><td>自定义 iconfont 类前缀，一般留空</td></tr><tr><td>图标字号 / 颜色</td><td>字体图标样式</td></tr><tr><td>文字/emoji 备用</td><td>无图且无图标名时显示，如 📢</td></tr></tbody></table><p><strong>文字样式</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>文字颜色 / 字号 / 字重</td><td>通知正文样式</td></tr><tr><td>对齐</td><td>左 / 中 / 右</td></tr></tbody></table><p><strong>操作</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>可关闭</td><td>用户是否可点 × 关闭（关闭后当次会话内隐藏）</td></tr><tr><td>操作按钮</td><td>是否显示右侧按钮</td></tr><tr><td>按钮文字 / 背景 / 文字色</td><td>开启操作按钮时可配置</td></tr></tbody></table><h3 id="样式说明-1" tabindex="-1">样式说明 <a class="header-anchor" href="#样式说明-1" aria-label="Permalink to &quot;样式说明&quot;">​</a></h3><p>横条整体背景、内边距、圆角、外边距在 <strong>样式</strong> Tab 设置。若希望通知「贴边通栏」，可将左右外边距设为 0，并配合页面背景色。</p><h3 id="注意事项-1" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-1" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>左侧展示方式 <strong>只生效一种</strong>：有图片就不显示图标字体。</li><li>当前编辑器以 <strong>单条通知文字</strong> 为主；多条轮播能力以客户端实际渲染为准。</li><li>关闭后是否再次展示取决于客户端逻辑，重要通知请同时在消息中心或弹窗中同步触达。</li></ul><hr><h2 id="结束文本-xiaoyi-no-more" tabindex="-1">结束文本（xiaoyi-no-more） <a class="header-anchor" href="#结束文本-xiaoyi-no-more" aria-label="Permalink to &quot;结束文本（xiaoyi-no-more）&quot;">​</a></h2><h3 id="说明-2" tabindex="-1">说明 <a class="header-anchor" href="#说明-2" aria-label="Permalink to &quot;说明&quot;">​</a></h3><p>列表 <strong>底部状态条</strong>：展示「加载中…」「没有更多了」「加载失败」等文案，加载中时可带转圈图标，失败时可带 <strong>重试</strong> 链接。</p><p>有两种用法：</p><ol><li><strong>普通结束语</strong>：手动选状态，用于自定义页装饰或预览某一态的样式。</li><li><strong>首页列表页脚</strong>（<code>homeListFooter = true</code>）：放在 <strong>圈子列表 / 笔记列表 / 笔记瀑布流</strong> 下方，运行时由首页数据 <strong>自动切换</strong> 加载中 ↔ 没有更多 ↔ 失败，编辑器里仅作样式预览。</li></ol><h3 id="适用页面-2" tabindex="-1">适用页面 <a class="header-anchor" href="#适用页面-2" aria-label="Permalink to &quot;适用页面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面类型</th><th>是否常用</th></tr></thead><tbody><tr><td>应用首页（含列表区块）</td><td>常用（作为列表页脚）</td></tr><tr><td>发现页</td><td>按需</td></tr><tr><td>自定义页面</td><td>仅作静态装饰时</td></tr></tbody></table><h3 id="属性配置-2" tabindex="-1">属性配置 <a class="header-anchor" href="#属性配置-2" aria-label="Permalink to &quot;属性配置&quot;">​</a></h3><p><strong>列表底部模式</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>homeListFooter</td><td>为「列表页脚」时由系统自动控制状态；属性里 <strong>当前状态</strong> 仅用于预览样式</td></tr></tbody></table><p><strong>状态与文案</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>当前状态</td><td><strong>加载中</strong> / <strong>没有更多</strong> / <strong>错误</strong>（非页脚模式时手动切换预览）</td></tr><tr><td>完成文字</td><td>没有更多时的文案，如 <code>- THE END -</code></td></tr><tr><td>加载文字</td><td>加载中的文案，如 <code>加载中...</code></td></tr><tr><td>错误文字</td><td>失败时的文案，如 <code>加载失败</code></td></tr></tbody></table><p><strong>样式</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>字号 / 文字颜色 / 字重</td><td>状态文字样式</td></tr><tr><td>加载图标色</td><td>加载中转圈颜色；可设透明</td></tr></tbody></table><p><strong>重试</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>显示重试</td><td>错误态是否显示可点重试</td></tr><tr><td>重试文字 / 颜色</td><td>如「点击重试」</td></tr></tbody></table><h3 id="样式说明-2" tabindex="-1">样式说明 <a class="header-anchor" href="#样式说明-2" aria-label="Permalink to &quot;样式说明&quot;">​</a></h3><p>页脚组件通常 <strong>不需要背景块</strong>，在 <strong>样式</strong> Tab 设 <code>marginTop</code> 与列表拉开距离即可。字号建议 22~26 rpx，颜色用浅灰（如 <code>#999999</code>）以免抢列表内容注意力。</p><h3 id="注意事项-2" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-2" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>作为首页列表页脚时，须放在 <strong>笔记列表、圈子列表或瀑布流</strong> 正下方，且同一首页建议 <strong>只放一个</strong> 页脚组件。</li><li><code>homeListFooter</code> 为 true 时，<strong>不要</strong> 指望手动切换「当前状态」能改变线上行为——线上由接口分页自动控制。</li><li>若列表上方使用了 <strong>筛选标签</strong> 联动，切换标签重新加载时，页脚会同步进入「加载中」态。</li></ul><hr><h2 id="系列导航" tabindex="-1">系列导航 <a class="header-anchor" href="#系列导航" aria-label="Permalink to &quot;系列导航&quot;">​</a></h2><ul><li>上一篇：<a href="/features/ui-editor/components-layout">布局导航组件</a></li><li>下一篇：<a href="/features/ui-editor/components-community">社区内容组件</a></li></ul>',61)])])}const u=r(e,[["render",n]]);export{c as __pageData,u as default};
